//
//  DS4EngineShimSourcesParityTests.swift
//  ZenCODE
//
//  The installed `zen` binary carries the DS4 engine shim sources and build
//  script as strings generated by `Scripts/GenerateDS4EngineShimSources.swift`.
//  These tests keep them byte-identical to the canonical files in the repository.
//

import Foundation
import Testing
@testable import ZenCODECore

@Suite
struct DS4EngineShimSourcesParityTests {
    /// Repository root, derived from this file: Tests/ZenCODECoreTests/Local/DS4/<file>.
    private static let repositoryRoot: URL = {
        var url = URL(fileURLWithPath: #filePath)
        for _ in 0..<5 {
            url.deleteLastPathComponent()
        }
        return url
    }()

    private static func canonicalData(_ relativePath: String) throws -> Data {
        let url = repositoryRoot.appendingPathComponent(relativePath)
        return try Data(contentsOf: url)
    }

    private static let abiHeaderPath = "Sources/ZenCODECore/Resources/DS4Engine/zencode_ds4_abi.h"
    private static let shimSourcePath = "Sources/ZenCODECore/Resources/DS4Engine/zencode_ds4_shim.c"
    private static let buildScriptPath = "Scripts/build-ds4-engine.sh"

    @Test
    func embeddedABIHeaderMatchesCanonicalFile() throws {
        let canonical = try Self.canonicalData(Self.abiHeaderPath)
        #expect(!canonical.isEmpty)
        #expect(Data(DS4EngineShimSources.abiHeader.utf8) == canonical)
    }

    @Test
    func embeddedShimSourceMatchesCanonicalFile() throws {
        let canonical = try Self.canonicalData(Self.shimSourcePath)
        #expect(!canonical.isEmpty)
        #expect(Data(DS4EngineShimSources.shimSource.utf8) == canonical)
    }

    @Test
    func embeddedBuildScriptMatchesCanonicalFile() throws {
        let canonical = try Self.canonicalData(Self.buildScriptPath)
        #expect(!canonical.isEmpty)
        #expect(Data(DS4EngineShimSources.buildScript.utf8) == canonical)
    }

    @Test
    func embeddedFilesKeepTheirTrailingNewline() {
        #expect(DS4EngineShimSources.abiHeader.hasSuffix("\n"))
        #expect(DS4EngineShimSources.shimSource.hasSuffix("\n"))
        #expect(DS4EngineShimSources.buildScript.hasSuffix("\n"))
    }

    @Test
    func extractedFileNamesAndOrder() {
        #expect(DS4EngineShimSources.files.map(\.name) == [
            "zencode_ds4_abi.h",
            "zencode_ds4_shim.c",
            "build-ds4-engine.sh"
        ])
        #expect(DS4EngineShimSources.files.map(\.contents) == [
            DS4EngineShimSources.abiHeader,
            DS4EngineShimSources.shimSource,
            DS4EngineShimSources.buildScript
        ])
    }

    @Test
    func headerABIVersionMatchesExpectedVersion() throws {
        let embedded = Self.abiVersion(inHeader: DS4EngineShimSources.abiHeader)
        #expect(embedded == DS4EngineABI.expectedVersion)

        let canonical = try String(
            contentsOf: Self.repositoryRoot.appendingPathComponent(Self.abiHeaderPath),
            encoding: .utf8
        )
        #expect(Self.abiVersion(inHeader: canonical) == DS4EngineABI.expectedVersion)
    }

    @Test
    func buildScriptIsABashScript() {
        let script = DS4EngineShimSources.buildScript
        #expect(script.hasPrefix("#!/usr/bin/env bash\n"))
        #expect(script.contains("set -euo pipefail"))
    }

    private static func abiVersion(inHeader header: String) -> Int32? {
        for line in header.split(separator: "\n") {
            let words = line.split(whereSeparator: { $0 == " " || $0 == "\t" })
            if words.count >= 3, words[0] == "#define", words[1] == "ZENCODE_DS4_ABI_VERSION" {
                return Int32(words[2])
            }
        }
        return nil
    }
}
